query:
-- Update existing rows where contracting is not full
UPDATE modulePermissions SET accessLevel = 'full' WHERE module = 'contracting' AND accessLevel != 'full';

-- Insert full contracting access for users who have no contracting row at all
INSERT INTO modulePermissions (userId, module, accessLevel)
SELECT u.id, 'contracting', 'full'
FROM users u
WHERE u.id NOT IN (
  SELECT userId FROM modulePermissions WHERE module = 'contracting'
);

-- Also grant clientDocs full access to all users
UPDATE modulePermissions SET accessLevel = 'full' WHERE module = 'clientDocs' AND accessLevel != 'full';

INSERT INTO modulePermissions (userId, module, accessLevel)
SELECT u.id, 'clientDocs', 'full'
FROM users u
WHERE u.id NOT IN (
  SELECT userId FROM modulePermissions WHERE module = 'clientDocs'
);

